var i=`0763-pilau-kenyan-style`;var n=`world-0763`;var o=`KE`;var a=`eastern-africa`;var r=4;var s=60;var u={en:`Pilau Kenyan Style`,ua:`Пілау по-кенійськи`};var l={en:`Pilau Kenyan Style is a Kenya classic prepared with beef chuck, yellow onion, garlic, ginger root. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Пілау по-кенійськи, страва кухні країни Кенія зі складниками: яловича лопатка, жовта цибуля, часник, корінь імбиру. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,590,`g`],[`yellow-onion`,190,`g`],[`sunflower-oil`,50,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`garlic`,4,`clove`],[`ginger-root`,20,`g`],[`ground-cumin`,5,`g`],[`ground-cardamom`,4,`g`],[`ground-cloves`,2,`g`]]},{en:`Coat the rice in the warm fat with the aromatics and toast gently for about 5 minutes without browning.`,ua:`Змішайте рис із теплим жиром та ароматичними складниками й прогрівайте приблизно 5 хвилин, не підрум’янюючи.`,t:[`sauteing`,`risotto-method`],m:5,i:[[`basmati-rice`,360,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`beef-stock`,760,`ml`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 9 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 9 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:9,i:[]}];var d={slug:i,id:n,country:`KE`,region:a,servings:4,minutes:60,title:u,text:l,steps:g};export{o as country,d as default,n as id,s as minutes,a as region,r as servings,i as slug,g as steps,l as text,u as title};